<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';
import { savedAcademicTerm, saveAcademicTerm, academicTermLabel, semesterLabel } from '../services/academic-term';

const auth=useAuthStore(),admin=computed(()=>auth.user?.role==='ADMIN'),student=computed(()=>auth.user?.role==='STUDENT'),faculty=computed(()=>auth.user?.role==='FACULTY');
const tab=ref('encoding'),policy=ref(null),offerings=ref([]),terms=ref([]),selected=ref(''),rows=ref([]),loading=ref(true),saving=ref(false),error=ref(''),notice=ref('');
const termFilter=ref(savedAcademicTerm(auth.user?.id));
watch(termFilter,value=>{saveAcademicTerm(auth.user?.id,value);selected.value='';rows.value=[];});
const visibleOfferings=computed(()=>offerings.value.filter(item=>!termFilter.value||String(item.termId)===String(termFilter.value)));
const policyForm=ref({label:'',minimum:'',maximum:'',passingValue:'',passDirection:'',reason:''}),editValues=ref({}),search=ref(''),workflowFilter=ref('');
const selectedOffering=computed(()=>offerings.value.find(item=>String(item.id)===String(selected.value)));
const filtered=computed(()=>rows.value.filter(row=>{const query=search.value.trim().toLowerCase();return (!query||`${row.studentId} ${row.firstName} ${row.lastName}`.toLowerCase().includes(query))&&(!workflowFilter.value||(row.gradeStatus||'NOT_GRADED')===workflowFilter.value);}));
const counts=computed(()=>({passed:rows.value.filter(row=>row.remark==='PASSED').length,failed:rows.value.filter(row=>row.remark==='FAILED').length,notGraded:rows.value.filter(row=>row.enrollmentStatus==='ENROLLED'&&!row.gradeStatus).length,submitted:rows.value.filter(row=>row.gradeStatus==='SUBMITTED').length}));
function dirty(row){return String(editValues.value[row.enrollmentId]??'')!==String(row.value??'');}
async function load(){loading.value=true;error.value='';try{const requests=[api.get('/grades/policy'),student.value?api.get('/grades'):api.get('/academic/offerings'),api.get('/academic/terms')];const results=await Promise.all(requests);policy.value=results[0].data.data;terms.value=results[2].data.data;if(student.value)rows.value=results[1].data.data;else offerings.value=results[1].data.data;if(policy.value)policyForm.value={label:policy.value.label,minimum:policy.value.minimum,maximum:policy.value.maximum,passingValue:policy.value.passingValue??'',passDirection:policy.value.passDirection??'',reason:''};}catch(e){error.value=e.response?.data?.message||'Could not load grades.';}finally{loading.value=false;}}
async function loadRoster(){search.value='';workflowFilter.value='';if(!selected.value){rows.value=[];return;}error.value='';try{rows.value=(await api.get('/grades',{params:{offeringId:selected.value}})).data.data;editValues.value=Object.fromEntries(rows.value.map(row=>[row.enrollmentId,row.value??'']));}catch(e){error.value=e.response?.data?.message||'Could not load grade roster.';}}
async function savePolicy(){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{await api.put('/grades/policy',policyForm.value);notice.value='School grading policy saved as a new version.';await load();}catch(e){error.value=e.response?.data?.message||'Could not save the grading policy.';}finally{saving.value=false;}}
async function saveDraft(row){if(saving.value)return;saving.value=true;error.value='';notice.value='';try{await api.put(`/grades/${row.enrollmentId}`,{value:editValues.value[row.enrollmentId],version:row.version||undefined});notice.value='Draft saved.';await loadRoster();}catch(e){error.value=e.response?.data?.message||'Could not save the draft.';}finally{saving.value=false;}}
async function action(row,kind,choice){if(saving.value)return;let body={};if(kind==='decision'){const decision=choice;if(decision==='APPROVE'&&!window.confirm(`Approve and publish the submitted grade for ${row.firstName} ${row.lastName}?`))return;body={decision};if(decision==='RETURN'){const reason=window.prompt('Reason for returning this grade:');if(!reason?.trim())return;body.reason=reason.trim();}}else if(kind==='reopen'){const reason=window.prompt('Reason for reopening this published grade:');if(!reason?.trim())return;body.reason=reason.trim();}else if(!window.confirm(`Submit the saved draft for ${row.firstName} ${row.lastName} to an administrator?`))return;
  saving.value=true;error.value='';notice.value='';try{await api.post(`/grades/${row.enrollmentId}/${kind}`,body);notice.value=kind==='submit'?'Grade submitted for review.':kind==='reopen'?'Grade reopened for correction.':'Review decision saved.';await loadRoster();if(kind==='decision')window.dispatchEvent(new Event('sbaa:notifications'));}catch(e){error.value=e.response?.data?.message||'Could not complete the grade action.';}finally{saving.value=false;}}
async function exportCsv(){error.value='';try{const response=await api.get('/grades/export.csv',{params:student.value?{}:{offeringId:selected.value},responseType:'blob'});const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download='sbaa-grade-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e.response?.data?.message||'Could not export grades.';}}
function printReport(){window.print();}
onMounted(load);
</script>
<template><PortalLayout title="Grades"><div class="dashboard content-page grades-page"><div class="page-heading"><div><p class="eyebrow">ACADEMIC RECORDS</p><h2>{{student?'My grades':'Class grades'}}</h2><p>Only approved and published grades are visible to students. Missing grades are not failures.</p></div></div><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p><p v-if="loading" class="empty">Loading grades…</p><template v-else>
  <section v-if="student" class="panel"><div class="panel-title"><h2>Published grades</h2><div class="inline-actions"><button class="secondary-button" :disabled="!rows.length" @click="exportCsv">Download CSV</button><button class="secondary-button" :disabled="!rows.length" @click="printReport">Print / save PDF</button></div></div><div v-if="rows.length" class="record-list"><div v-for="row in rows" :key="row.id" class="record-row"><div><strong>{{row.code}} — {{row.name}}</strong><span>{{row.academicYear}} · {{row.semester}} · Section {{row.section}} · {{row.units}} units</span><small>{{row.remark||'Remark not configured'}} · Policy version {{row.policyVersionId||'not recorded'}}</small></div><strong>{{row.value}}</strong></div></div><p v-else class="empty">No published grades yet.</p></section>
  <template v-else><div class="grade-tabs" role="tablist" aria-label="Grade tasks"><button role="tab" :aria-selected="tab==='encoding'" :class="{active:tab==='encoding'}" @click="tab='encoding'">Grade Encoding</button><button role="tab" :aria-selected="tab==='review'" :class="{active:tab==='review'}" @click="tab='review'">Review &amp; Publication</button><button v-if="admin" role="tab" :aria-selected="tab==='policy'" :class="{active:tab==='policy'}" @click="tab='policy'">Grading Policy</button></div>
  <section v-if="tab==='policy'&&admin" class="panel narrow-panel" role="tabpanel"><h2>School grading policy</h2><p>The approved passing rule must come from school policy. A new policy version applies to future grade drafts; historical grades keep their recorded version.</p><form class="stack-form" @submit.prevent="savePolicy"><label>Scale name<input v-model="policyForm.label" required maxlength="100" placeholder="School-approved scale"/></label><div class="two-fields"><label>Minimum<input v-model="policyForm.minimum" type="number" step="0.01" required/></label><label>Maximum<input v-model="policyForm.maximum" type="number" step="0.01" required/></label></div><div class="two-fields"><label>Official passing value (leave blank until approved)<input v-model="policyForm.passingValue" type="number" step="0.01"/></label><label>Passing rule<select v-model="policyForm.passDirection"><option value="">Not configured</option><option value="AT_LEAST">Grade is at least the passing value</option><option value="AT_MOST">Grade is at most the passing value</option></select></label></div><label>Reason for configuration<input v-model="policyForm.reason" required maxlength="500"/></label><button class="primary" :disabled="saving">Save policy version</button></form></section>
  <section v-if="tab!=='policy'" class="panel" role="tabpanel"><h2>Class assignment</h2><div class="two-fields"><label>Academic term (shared across academic pages)<select v-model="termFilter"><option value="">All terms</option><option v-for="term in terms" :key="term.id" :value="term.id">{{academicTermLabel(term)}}</option></select></label><label class="grade-select">Select class<select v-model="selected" @change="loadRoster"><option value="">Choose a class</option><option v-for="offering in visibleOfferings" :key="offering.id" :value="offering.id">{{offering.code}} — {{offering.name}} · Section {{offering.section}} · {{semesterLabel(offering.semester)}} · AY {{offering.academicYear}}</option></select></label></div><p v-if="selectedOffering" class="grade-context">{{selectedOffering.name}} · Section {{selectedOffering.section}} · Teacher {{selectedOffering.faculty||'Unassigned'}} · {{selectedOffering.enrollmentCount??rows.length}} enrolled</p><p v-if="!policy" class="form-error" role="status">An administrator must configure the approved grade range before encoding.</p><p v-else-if="policy.passingValue==null" class="form-error" role="status">The official passing rule is not configured. Drafts can be saved, but they cannot be submitted or published yet.</p><div v-if="selected" class="inline-actions"><button class="secondary-button" @click="exportCsv">Download authorized CSV</button><button class="secondary-button" @click="printReport">Print / save PDF</button></div></section>
  <section v-if="tab!=='policy'&&selected" class="panel" role="tabpanel"><div class="panel-title"><h2>{{tab==='encoding'?'Grade Encoding':'Review & Publication'}}</h2><p>{{rows.length}} roster records</p></div><div class="grade-summary"><span>{{counts.passed}} Passed</span><span>{{counts.failed}} Failed</span><span>{{counts.notGraded}} Not yet graded</span><span>{{counts.submitted}} Awaiting review</span></div><div class="toolbar"><label>Search roster<input v-model="search" placeholder="Student ID or name"/></label><label>Workflow<select v-model="workflowFilter"><option value="">All statuses</option><option value="NOT_GRADED">Not yet graded</option><option value="DRAFT">Draft</option><option value="SUBMITTED">Submitted</option><option value="PUBLISHED">Published</option></select></label></div><p v-if="!filtered.length" class="empty">No students match these filters.</p><div v-else class="record-list"><article v-for="row in filtered" :key="row.enrollmentId" class="grade-row"><div><strong>{{row.lastName}}, {{row.firstName}}</strong><small>{{row.studentId}} · {{row.enrollmentStatus}} · {{row.gradeStatus||'Not yet graded'}}<template v-if="row.version"> · Version {{row.version}}</template></small><small v-if="row.remark">{{row.remark}} · Policy version {{row.policyVersionId}}</small><small v-else-if="row.value!=null">Academic remark pending approved policy</small></div><form v-if="tab==='encoding'&&faculty&&row.enrollmentStatus==='ENROLLED'&&(!row.gradeStatus||row.gradeStatus==='DRAFT')" class="grade-editor" @submit.prevent="saveDraft(row)"><label>Grade<input v-model="editValues[row.enrollmentId]" type="number" step="0.01" :min="policy?.minimum" :max="policy?.maximum" required :disabled="!policy"/></label><span v-if="dirty(row)" class="grade-dirty">Unsaved change</span><button class="secondary-button" :disabled="saving||!policy">Save draft</button><button v-if="row.gradeStatus==='DRAFT'" type="button" class="secondary-button" :disabled="saving||dirty(row)||policy?.passingValue==null" @click="action(row,'submit')">Submit for review</button></form><div v-else-if="tab==='review'&&admin&&row.gradeStatus==='SUBMITTED'" class="inline-actions"><strong>{{row.value}}</strong><button class="secondary-button" :disabled="saving" @click="action(row,'decision','APPROVE')">Approve &amp; publish</button><button class="secondary-button" :disabled="saving" @click="action(row,'decision','RETURN')">Return for correction</button></div><div v-else-if="admin&&row.gradeStatus==='PUBLISHED'" class="inline-actions"><strong>{{row.value}}</strong><button v-if="tab==='review'" class="secondary-button" :disabled="saving" @click="action(row,'reopen')">Reopen for correction</button></div><strong v-else-if="row.value!=null">{{row.value}}</strong></article></div></section></template>
  </template></div></PortalLayout></template>
<style scoped>.grade-tabs{display:flex;gap:.5rem;flex-wrap:wrap;border-bottom:1px solid var(--border)}.grade-tabs button{border:0;background:transparent;color:var(--muted);padding:.7rem 1rem;font-weight:700}.grade-tabs button.active{color:var(--accent);border-bottom:3px solid var(--accent)}.grade-context{margin:1rem 0}.grade-summary{display:flex;gap:.5rem;flex-wrap:wrap;margin:1rem 0}.grade-summary span{padding:.35rem .65rem;border-radius:20px;background:var(--surface-soft);font-size:.8rem}.grade-dirty{color:var(--accent);font-size:.8rem;font-weight:700}@media print{.grade-tabs,.grade-editor,.toolbar,.inline-actions,.portal aside,.portal-header{display:none!important}.portal{display:block}.grades-page{padding:0}.panel{box-shadow:none}}</style>
